import{_ as p,o as t,c as e,a3 as _}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/59-当危险变得不易察觉.md","filePath":"books/attached/59-当危险变得不易察觉.md","lastUpdated":1794298621000}'),o={name:"books/attached/59-当危险变得不易察觉.md"};function r(s,a,d,n,c,i){return t(),e("div",null,[...a[0]||(a[0]=[_('<h3 id="当危险变得不易察觉" tabindex="-1">当危险变得不易察觉 <a class="header-anchor" href="#当危险变得不易察觉" aria-label="Permalink to &quot;当危险变得不易察觉&quot;">​</a></h3><p>像斯坦这样的安全型依恋人群，的确有出众的优秀品质，但并不容易被人发现。他们对伴侣的爱与责任都是出于自我本能，并不会担心自己失去伴侣的爱。他们对于亲密感非常从容，并且有着出众的能力，充分表达自己的需求，同时也能通过沟通很好地了解伴侣的需求。</p><p>事实上，有许多研究都致力于人们的无意识思维，正如第6章提到的那样，测量人们对于屏幕上一闪而过词语的反应时。通过对于人们无意识思维的研究，比较三种依恋风格人群的反应方式，有研究发现，安全型依恋风格的人，对于诸如爱、拥抱和亲密等主题的词语有着更强的下意识反应，而对于诸如危险、丧失和分离这类词语则没那么敏感。也就是说，带有威胁性的词汇对他们来说没那么容易进入意识。然而，相比于回避型人格一开始对于威胁性的词汇并不灵敏，在分心任务之下变得灵敏。安全型人群即使在注意分散的情形之下，依然对威胁性的词汇不那么敏感。也就是说，不同于回避型人群，安全型依恋风格的人即使放下戒备，也并不担心恋情中的威胁。换句话说，他们无须努力压抑自己的情绪，无论在意识层面还是潜意识的层面，他们都不怎么在意这些事情！不仅如此，在这项实验中，当安全型依恋风格的被试被要求可以想起分离、抛弃或者丧失的时候，他们的皮肤导电测试结果显示，他们仍然会对这些威胁产生紧张感，因为皮肤分泌的汗液会增多。然而，一旦要求他们停止这种想法，皮肤上的汗液立马会恢复正常水平。因此我们就不难理解，为什么对于某些人来说，面对恋情中的威胁很难平复情绪，但是对于安全型人群却易如反掌。他们只是对于消极线索没那么敏感而已。</p><p>而这种特质会影响到他们亲密关系的方方面面，比如：</p><p>-最佳冲突克星——在争吵中，安全型依恋风格的人不会表现得回避畏缩，也不会试图去伤害和攻击对方，反而会努力将激进的局面平复下来。</p><p>-善于调整心态——他们并不会因为诟病而气馁。他们十分乐于反思和检讨自己的行为，如果有必要的话，甚至愿意调整自己的信念和策略。</p><p>-期望有效沟通——他们希望自己的伴侣多一些理解和反馈，他们自有这种能力，将自己的感受从容而精准地传达给自己的伴侣。</p><p>-拒绝感情把戏——他们期望亲密感，也相信对方和自己一样，所以何苦去玩什么把戏呢？</p><p>-不抗拒亲密，不刻意划界——他们乐于追寻亲密感，也不畏惧于“沉迷恋情不可自拔”。因为他们不像焦虑型人群一样，成天担心自己在恋情中落入下风，也不像回避型人群一样，需要消退激情。不管是在生理上还是情感上，他们都非常享受亲密感的存在。</p><p>-容易宽恕他人——他们总会将伴侣的出发点假定为善意的，因此即使是伴侣伤害了他们，也非常容易宽恕对方。</p><p>-接受身体和感情的合二为一——并不需要刻意与对方分开，来营造距离产生的美感。能够在身体和情感上同时与伴侣产生融合。</p><p>-将伴侣视为掌上明珠——一旦你成了安全型人群的亲密伴侣，他们会对你充满爱和尊重。</p><p>-努力增进彼此感情——他们对自己的亲密关系充满乐观和自信，总是带着善意揣测双方的感情。</p><p>-伴侣愉悦为己任——他们希望对方对自己充满爱与责任，而自己也以此回报对方。</p><p>许多人只经历过非安全型的伴侣，因此他们很难想象和安全型伴侣在一起的生活，是有多么的大相径庭。首先，安全型伴侣并不会出现治疗者们经常提到的“关系舞蹈”情形，也就是伴侣中的一方渴望两人更亲密，而另一方则时刻在亲密关系中保持着某种距离感。而相反，与安全型伴侣在一起，取而代之的是一种日渐亲密的感觉。其次，他们会非常敏锐而共情地与恋人探讨感情问题，更加难能可贵的是，他们能够从始至终保持这种状态。最后，安全型依恋风格的人群，会将自己的伴侣纳入一个情感安全地带，帮助他们更有勇气、更从容地面对外面的世界。而作为伴侣，很多人只有在失去了他们以后，才发现这一切是多么的可贵。当人们先后和安全型与非安全型的伴侣交往过后，普遍会对安全型伴侣产生更多赞誉。这些人往往用经验告诉你，与两者交往的体验就是天壤之别。即使没有依恋风格理论的支撑，他们也能如数家珍一般道出两者的各种差别。</p>',15)])])}const m=p(o,[["render",r]]);export{h as __pageData,m as default};
